select * from 
(select
substr(order_date_key, 1, 6) yearmo,
concat(substr(order_date_key, 1, 6), analytic_business_unit, "All", "All") granularlity,
count(distinct(case when analytic_business_unit = 'Home' then account_id end)) levels_customers

from bigfoot_external_neo.cp_bi_prod_sales__forward_unit_history_fact sales

where lower(sales.status) in ('in_progress', 'undelivered', 'cancelled', 'completed', 'delivered', 'approved', 'shipped', 'ready_to_ship', 'returned', 'return_requested', 'activated')
and sales.type != 'service'
and sales.replacement_for_unit IS NULL
and sales.exchange_for_unit IS NULL
and sales.is_freebie = FALSE
and sales.marketplace_id IN ('FLIPKART')
and sales.analytic_business_unit IN ('Home')
and ((sales.order_date_key between 20250101 and 20250727) or (sales.order_date_key between 20240101 and 20240727))
and sales.order_date_key not in (20240229)
and sales.is_shopsy_order = FALSE

group by
substr(order_date_key, 1, 6),
concat(substr(order_date_key, 1, 6), analytic_business_unit, "All", "All")

union all

select
substr(order_date_key, 1, 6) yearmo,
concat(substr(order_date_key, 1, 6), analytic_business_unit, analytic_super_category, "All") granularlity,
count(distinct case when lower(analytic_super_category) in ('household','homedecor','homefurnishing','homeimprovementtool') then account_id end) levels_customers

from bigfoot_external_neo.cp_bi_prod_sales__forward_unit_history_fact sales

where lower(sales.status) in ('in_progress', 'undelivered', 'cancelled', 'completed', 'delivered', 'approved', 'shipped', 'ready_to_ship', 'returned', 'return_requested', 'activated')
and sales.type != 'service'
